  }, handlers = handler_debug(enable = TRUE, uuid = TRUE), enable = TRUE, interval = 0,
     delay_terminal = FALSE, delay_stdout = FALSE, delay_conditions = character()))
  list(events = plain, uuid_events = marked)
}

